window.SKIM_PAPERS["1506.06724"] = {"concepts": [{"id": "bookcorpus-dataset", "name": "BookCorpus: what it contains", "tier": "minor", "parent": null, "summary": "A collection of 11,038 free books scraped from the web, written by authors the paper describes as yet unpublished, totalling roughly 74 million sentences and 985 million words. It was assembled as training material for an unsupervised sentence-representation model, not as an evaluation benchmark.", "explanation": "The corpus is gathered by collecting free books available on the web from self-publishing authors; the paper calls them \"free books written by yet unpublished authors\" and gives no further sourcing detail. The only stated inclusion filter is a length threshold: books with fewer than 20,000 words are dropped, on the stated reasoning that shorter stories are likely noisier. The result spans 16 genres, with the largest being Romance (2,865 books), Fantasy (1,479), Science fiction (786) and Teen (430); the genre labels come with the books rather than from any classifier the paper describes. The summary table reports 11,038 books, 74,004,228 sentences, 984,846,357 words, 1,316,420 unique word types, a mean of 13 words per sentence and a median of 11. That vocabulary figure is large for a corpus of this size, which the paper elsewhere attributes to the linguistic variety of literature: different writing styles, formatting, slang and dialect spellings (\"going\" versus \"goin'\", \"was\" versus \"'us\"). Sentence segmentation is done automatically; the paper describes parsing books into sentences, paragraphs (from indentation) and chapters (a title that is indented, starts a new page and does not end with an end symbol), though it states that procedure for its separate movie-aligned book set. Genre diversity and sheer size are the two properties the paper points to when it argues the corpus supports \"very general\" text representations. Note that the corpus is distinct from the paper's other dataset, an 11 movie/book pair set with 2,070 human-annotated shot-to-sentence correspondences used only for evaluating alignment.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 3, \"The BookCorpus Dataset\" paragraph; Table 2 (summary statistics). Sentence/paragraph/chapter parsing is described in the same section under \"The MovieBook Dataset\".", "ownerPaper": "1506.06724", "sources": {"paperId": "1506.06724", "note": "Section 3, \"The BookCorpus Dataset\" paragraph; Table 2 (summary statistics). Sentence/paragraph/chapter parsing is described in the same section under \"The MovieBook Dataset\".", "sections": [], "pages": []}}, {"id": "contiguous-text-requirement", "name": "Why a book corpus: contiguous running text", "tier": "minor", "parent": null, "summary": "The training objective predicts a sentence's neighbours, so it only produces a learning signal on text where sentences genuinely follow one another in order. Books are chosen because they supply long, ordered, single-author passages at scale rather than isolated sentences.", "explanation": "The paper states the constraint directly: \"the learning signal of the model depends on having contiguous text, where sentences follow one another in sequence,\" and concludes that a large collection of books is therefore a natural corpus. This matters because the objective is trained on triples of consecutive sentences (s_{i-1}, s_i, s_{i+1}); a corpus of shuffled or independently-collected sentences would supply triples whose neighbours carry no predictable relationship, and the target distribution the decoders are asked to model would be close to noise. Books also give very long unbroken spans — the associated movie-aligned books run from 638 to 15,498 sentences each, with an average around 7,750 — so context does not reset every few sentences. The paper's second argument for books is coverage: given the size and the spread across 16 genres, the corpus is claimed to allow learning of \"very general\" representations of text. Books are also argued to carry content that short captions do not: fine-grained visual detail (how a person, object or scene looks) and high-level semantics (what characters think and feel, and how those states evolve across a story). The evidence offered in this paper for generality is qualitative rather than measured: nearest-neighbour retrievals for query sentences drawn from held-out books the model never trained on, shown as a table of four neighbours per query, which the authors read as syntactically and semantically similar. A companion reference is cited for quantitative benchmark results and for scaling the vocabulary to millions of words, so the claim of general-purpose representations is not established inside this paper.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.1 (paragraph beginning \"The learning signal of the model depends on...\"); Table 3 (held-out nearest-neighbour examples); Section 1 and Section 3 for the descriptive-richness argument and per-book sentence counts (Table 1).", "ownerPaper": "1506.06724", "sources": {"paperId": "1506.06724", "note": "Section 4.1 (paragraph beginning \"The learning signal of the model depends on...\"); Table 3 (held-out nearest-neighbour examples); Section 1 and Section 3 for the descriptive-richness argument and per-book sentence counts (Table 1).", "sections": [], "pages": []}}, {"id": "skip-thought-objective", "name": "Skip-thought: the objective the corpus feeds", "tier": "minor", "parent": null, "summary": "An encoder RNN compresses a sentence into a fixed vector, and two decoder RNNs conditioned on that vector try to generate the preceding and the following sentence. Training maximises the log-probability of both neighbours; the encoder output is then used as a general sentence embedding.", "explanation": "The model is described as the sentence-level analogue of skip-gram: instead of a word predicting its surrounding words, a sentence predicts its surrounding sentences, on the distributional-hypothesis reasoning that sentences appearing in similar contexts are likely to be semantically and syntactically similar. Encoder and decoders are GRUs, chosen over LSTMs on the grounds that GRUs match LSTM performance on sequence-prediction tasks while being simpler. The encoder runs h_t = (1 - z_t) ⊙ h_{t-1} + z_t ⊙ h̄_t, with update gate z_t = σ(W_z x_t + U_z h_{t-1}), proposed state h̄_t = tanh(W x_t + U(r_t ⊙ h_{t-1})) and reset gate r_t = σ(W_r x_t + U_r h_{t-1}), where x_t is the word embedding at step t; the final hidden state h_N = h_i is the vector for sentence s_i. Two separate decoders — one for s_{i-1}, one for s_{i+1} — use their own recurrent parameters but share a single vocabulary matrix V, and each gate and state update takes an extra conditioning term on h_i: z_t = σ(W^d_z x_{t-1} + U^d_z h_{t-1} + C_z h_i), r_t = σ(W^d_r x_{t-1} + U^d_r h_{t-1} + C_r h_i), h̄_t = tanh(W^d x_{t-1} + U^d(r_t ⊙ h_{t-1}) + C h_i). Word probabilities are P(w^t_{i+1} | w^{<t}_{i+1}, h_i) ∝ exp(v_{w^t_{i+1}} h^t_{i+1}), with v the row of V for that word. The objective for one triple is the sum of the two decoder log-likelihoods, Σ_t log P(w^t_{i+1} | w^{<t}_{i+1}, h_i) + Σ_t log P(w^t_{i-1} | w^{<t}_{i-1}, h_i), summed over all training triples and optimised with Adam. After training the decoders are discarded: any sentence is mapped through the encoder, and similarity between two sentences is the inner product of their vectors. The paper describes this as trained on millions of sentences from books and does not report hidden sizes, vocabulary size or training duration here, deferring those details to a companion reference.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.1 \"Skip-Thought Vectors\"; Equations 1-4 (encoder), 5-9 (decoder), 10 (objective); Figure 2 (architecture diagram).", "ownerPaper": "1506.06724", "sources": {"paperId": "1506.06724", "note": "Section 4.1 \"Skip-Thought Vectors\"; Equations 1-4 (encoder), 5-9 (decoder), 10 (objective); Figure 2 (architecture diagram).", "sections": [], "pages": []}}, {"id": "bookcorpus-provenance-gaps", "name": "What the paper does not specify about the corpus", "tier": "minor", "parent": null, "summary": "The corpus description is one paragraph and a statistics table. Source site, licensing, deduplication, cleaning, tokenisation and any released file list are not given, which limits how exactly the collection can be reproduced.", "explanation": "The paper says the books were collected \"from the web\" and are free books by unpublished authors, but it names no website, no crawl date and no license terms. No deduplication step is described, so near-duplicate books or repeated boilerplate are neither ruled out nor quantified. Preprocessing is likewise unstated for the corpus: the only cleaning step described anywhere in the paper is for a different dataset (removing names from movie descriptions and replacing them with a \"someone\" token). Sentence counts imply automatic segmentation, but the segmenter is not named, and the reported 1,316,420 unique words suggests little or no normalisation beyond whatever the tokeniser does — the paper itself notes that book text carries dialect spellings and slang that inflate vocabulary. The genre labels and counts are reported without saying whether they were supplied by the source site. The corpus is presented as a means to an end — training material for the sentence embedding used in the movie/book alignment experiments — rather than as a released, versioned resource, and the paper makes no distribution commitment. Anyone reconstructing it from this description would be matching aggregate statistics (11,038 books, ~74M sentences, ~985M words, minimum 20,000 words per book) rather than the exact book set.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 3, \"The BookCorpus Dataset\" paragraph and Table 2 (by what they state and omit); Section 4.2 for the one preprocessing step the paper does describe, applied to a different dataset.", "ownerPaper": "1506.06724", "sources": {"paperId": "1506.06724", "note": "Section 3, \"The BookCorpus Dataset\" paragraph and Table 2 (by what they state and omit); Section 4.2 for the one preprocessing step the paper does describe, applied to a different dataset.", "sections": [], "pages": []}}], "items": [], "edges": [], "themes": [], "pages": [], "narrative": null, "insights": null, "reading": [], "refs": {"accessed": []}, "regions": [], "pdfPages": 0, "readerKind": "pdf", "sections": []};
